#pragma once
#include "../../support.hpp"
namespace algs {
struct FileSystemNode { const std::string name; explicit FileSystemNode(std::string name): name(std::move(name)) {} virtual ~FileSystemNode() = default; virtual double size() const = 0; virtual std::vector<std::string> render(std::string indent = "") const = 0; };
class FileEntry : public FileSystemNode { double bytes; public: FileEntry(std::string name, double bytes): FileSystemNode(std::move(name)), bytes(bytes) {} double size() const override { return bytes; } std::vector<std::string> render(std::string indent = "") const override { return {indent + name + " (" + text(bytes) + ")"}; } };
class Directory : public FileSystemNode { std::vector<std::shared_ptr<FileSystemNode>> children; public: explicit Directory(std::string name): FileSystemNode(std::move(name)) {} template<class... Nodes> Directory& add(Nodes... nodes) { (children.push_back(std::move(nodes)), ...); return *this; } bool remove(const std::string& name) { auto it = std::find_if(children.begin(), children.end(), [&](auto& node) { return node->name == name; }); if (it == children.end()) return false; children.erase(it); return true; } double size() const override { double total = 0; for (auto& child : children) total += child->size(); return total; } std::vector<std::string> render(std::string indent = "") const override { std::vector<std::string> result{indent + name + "/ (" + text(size()) + ")"}; for (auto& child : children) { auto lines = child->render(indent + "  "); result.insert(result.end(), lines.begin(), lines.end()); } return result; } };
}
